CREATE TABLE IF NOT EXISTS documents (id SERIAL PRIMARY KEY, "originalName" VARCHAR(255) NOT NULL, "storedName" VARCHAR(255) UNIQUE NOT NULL, "mimeType" VARCHAR(255) NOT NULL, size INTEGER NOT NULL, path VARCHAR(500) NOT NULL, "uploadedBy" INTEGER NOT NULL REFERENCES users(id), "relatedType" VARCHAR(100), "relatedId" INTEGER, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(), "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS ticket_messages (id SERIAL PRIMARY KEY, "ticketId" INTEGER NOT NULL REFERENCES tickets(id) ON DELETE CASCADE, "authorId" INTEGER NOT NULL REFERENCES users(id), body TEXT NOT NULL, "isInternal" BOOLEAN NOT NULL DEFAULT FALSE, "slaDueAt" TIMESTAMPTZ, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(), "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS payments (id SERIAL PRIMARY KEY, "invoiceId" INTEGER NOT NULL REFERENCES invoices(id) ON DELETE CASCADE, amount DECIMAL(12,2) NOT NULL, method VARCHAR(100) NOT NULL, reference VARCHAR(255), "paidAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(), status VARCHAR(30) NOT NULL DEFAULT 'completed', "createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(), "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS quotations (id SERIAL PRIMARY KEY, number VARCHAR(255) UNIQUE NOT NULL, "clientId" INTEGER NOT NULL REFERENCES clients(id), title VARCHAR(255) NOT NULL, amount DECIMAL(12,2) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'draft', "validUntil" TIMESTAMPTZ, notes TEXT, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(), "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS role_permissions (id SERIAL PRIMARY KEY, "roleId" INTEGER NOT NULL REFERENCES roles(id) ON DELETE CASCADE, permission VARCHAR(255) NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(), "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE("roleId", permission));
INSERT INTO schema_migrations(version) VALUES ('002_extended_entities') ON CONFLICT (version) DO NOTHING;
